def find(items, target):
    for steps, item in enumerate(items, start=1):
        if item == target:
            return [steps - 1, steps]
    return [-1, len(items)]

def find(items, target):
    i = 0
    while i < len(items) and items[i] != target:
        i += 1
    if i == len(items):
        return [-1, i]
    return [i, i + 1]
